// Build digest from source file
const fs = require('fs');
const src = '$param:source_path';
let lines = [];
if (fs.existsSync(src)) {
  lines = fs.readFileSync(src, 'utf8').split('\n').filter(Boolean);
}
const title = '$param:digest_title' || '📋 Digest';
const body = lines.length
  ? lines.slice(-25).map(l => '• ' + l.replace(/^[\[{"].*?[,}]?/, '').slice(0, 120)).join('\n')
  : '_No new entries since last run._';
return [{ json: { content: `**${title}** (${lines.length} entries)\n${body}` } }];
